import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLong()) {
            long x = sc.nextLong();
            long y = sc.nextLong();
            long n = sc.nextLong();

            long a, b;
            float min, mi;
            if (y <= n) {
                a = x;
                b = y;
            } else {
                min = 1.0f;
                a = 0;
                b = 0;
                for (long i_iter = 1; i_iter <= n; i_iter++) {
                    long k = i_iter * x / y;
                    mi = (float) x / y - (float) k / i_iter;
                    if (mi < min) {
                        min = mi;
                        a = k;
                        b = i_iter;
                    }
                    mi = (float) (k + 1) / i_iter - (float) x / y;
                    if (mi < min) {
                        min = mi;
                        a = k + 1;
                        b = i_iter;
                    }
                }
            }

            long m, n_gcd;
            if (a > b) {
                m = a;
                n_gcd = b;
            } else {
                m = b;
                n_gcd = a;
            }

            if (n_gcd == 0) {
                m = 1;
            } else {
                long temp;
                long n_copy = n_gcd;
                long m_copy = m;
                while (n_copy != 0) {
                    temp = m_copy % n_copy;
                    m_copy = n_copy;
                    n_copy = temp;
                }
                // m now contains gcd
                m = m / m_copy;
                n_gcd = n_gcd / m_copy;
            }

            System.out.println(a / m + "/" + b / m);
        }
        sc.close();
    }
}
